minimal_patch:
在 scripts/lib/daily-task-board.mjs 的 recoverArtifact 中：
1. 将允许前缀状态从 ['generation_started','generation_unknown_no_repurchase'] 扩展为还包括 'incomplete_or_failed' 与该模块同步前的中间态；
2. 扫描候选时先按 artifact 文件 mtime 或 body 字段识别，若唯一候选的 body.date/run_key/task_id/logical_seat/source_commit 与当前 reservation 绑定一致但 body.status==='incomplete_or_failed'，则回填 seat.artifact 并将 seat.status 设为 'generation_failed_no_repurchase'，不重放模型调用；
3. 若候选为 complete 且通过 validateArtifact，则维持现有 generated_pending_sync 恢复。
具体修改：
```diff
-  if (!['generation_started','generation_unknown_no_repurchase'].includes(seat.status) || seat.artifact || !seat.assignment || !seat.claim_verified) return false;
+  if (!['generation_started','generation_unknown_no_repurchase','incomplete_or_failed'].includes(seat.status) || seat.artifact || !seat.assignment || !seat.claim_verified) return false;
```
并在 validateArtifact 前先尝试识别失败候选：
```js
+  const failMatches=[];
+  for (const name of fs.readdirSync(directory).filter(n=>n.startsWith(prefix) && n.endsWith('.json'))) {
+    const hash = name.slice(prefix.length,-5);
+    const candidatePath = path.join(directory,name);
+    try {
+      const bytes=fs.readFileSync(candidatePath);
+      if(!/^[a-f0-9]{64}$/.test(hash)||digest(bytes)!==hash) continue;
+      const body=JSON.parse(bytes);
+      if (body.date===record.date && body.run_key===record.run_key && body.task_id===seat.assignment.id && body.logical_seat===agent && body.source_commit===record.source_commit && body.status==='incomplete_or_failed') {
+        failMatches.push({path:`knowledge/results/daily-board/artifacts/${name}`,sha256:hash});
+      }
+    } catch {}
+  }
+  if (failMatches.length === 1) {
+    seat.artifact = failMatches[0];
+    seat.status = 'generation_failed_no_repurchase';
+    seat.recovery = 'immutable_failed_artifact_verified_no_model_replay';
+    saveLedger(root,record);
+    return true;
+  }
```
